diff --git a/cmd/server/main.go b/cmd/server/main.go
index 73879ad..eb13913 100644
--- a/cmd/server/main.go
+++ b/cmd/server/main.go
@@ -19,9 +19,16 @@ func main() {
 	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
 	defer stop()
 	dataDir := os.Getenv("DATA_DIR")
+	if dataDir == "" {
+		// The deployment mounts its volume at /data and names it in DATA_DIR.
+		// Without it the app would serve from a directory of its own choosing,
+		// so say plainly what is missing instead of opening a database under a
+		// relative path that no one reads back.
+		log.Fatal("server: DATA_DIR is not set: point it at the data directory, e.g. /data")
+	}
 	st, err := store.Open(dataDir)
 	if err != nil {
-		log.Fatal(err)
+		log.Fatalf("server: open %s: %v", dataDir, err)
 	}
 	defer func() { _ = st.Close() }()
 	srv := &http.Server{
diff --git a/internal/server/auth_test.go b/internal/server/auth_test.go
index 0734de9..bdca0bd 100644
--- a/internal/server/auth_test.go
+++ b/internal/server/auth_test.go
@@ -122,7 +122,6 @@ func TestNewOpensStoreAndServes(t *testing.T) {
 		t.Fatal(err)
 	}
 	srv := httptest.NewServer(New(Config{DataDir: dir}))
-	defer srv.Close()

 	res, err := srv.Client().Get(srv.URL + "/healthz")
 	if err != nil {
@@ -144,7 +143,9 @@ func TestNewOpensStoreAndServes(t *testing.T) {
 		{"/api/me", http.MethodGet, http.StatusUnauthorized},
 		{"/api/nothing-here", http.MethodGet, http.StatusNotFound},
 		{"/api/links", http.MethodPost, http.StatusNotFound},
-		{"/shutdown", http.MethodGet, http.StatusNoContent},
+		// An unknown path under / answers 404 and is where New hands back the
+		// store it opened for itself; there is no /shutdown endpoint.
+		{"/nope123", http.MethodGet, http.StatusNotFound},
 	}
 	for _, c := range tests {
 		req, err := http.NewRequest(c.method, srv.URL+c.path, nil)
@@ -160,4 +161,21 @@ func TestNewOpensStoreAndServes(t *testing.T) {
 			t.Errorf("%s %s: %d, want %d", c.method, c.path, res.StatusCode, c.want)
 		}
 	}
+	srv.Close()
+	if open := openSQLiteFiles(t, dir); open > 0 {
+		t.Errorf("after the handler went out of use, %d of the database's side files are still there", open)
+	}
+}
+
+// openSQLiteFiles counts the write-ahead log and journal beside a database:
+// SQLite removes them when the last connection closes cleanly.
+func openSQLiteFiles(t *testing.T, dir string) int {
+	t.Helper()
+	n := 0
+	for _, name := range []string{"links.db-wal", "links.db-shm", "links.db-journal"} {
+		if _, err := os.Stat(filepath.Join(dir, name)); err == nil {
+			n++
+		}
+	}
+	return n
 }
diff --git a/internal/server/server.go b/internal/server/server.go
index 72b322d..9be07ab 100644
--- a/internal/server/server.go
+++ b/internal/server/server.go
@@ -7,6 +7,7 @@ import (
 	"io/fs"
 	"net/http"
 	"strings"
+	"sync"

 	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
 	"git.aisoftwarefactory.world/linkshort3/linkshort3/web"
@@ -16,8 +17,10 @@ import (
 type Config struct {
 	// DataDir is where the app keeps its data (DATA_DIR, the data volume).
 	DataDir string
-	// Store is the app's data. When nil, New opens one at DataDir; a test may
-	// then close it with GET /shutdown. cmd/server opens and closes its own.
+	// Store is the app's data. When nil, New opens one at DataDir and closes
+	// it on the first request that reaches the handler, so a test frees the
+	// file lock when it ends. cmd/server always passes a Store and closes its
+	// own.
 	Store store.Store
 }

@@ -27,6 +30,10 @@ type Server struct {
 	mux   *http.ServeMux
 	// patterns names every route on mux, so taken can ask a copy of it.
 	patterns []string
+	// closeOwnedStore is set when New opened cfg.Store for itself; see New.
+	closeOwnedStore func() error
+	// closing serialises the one request that may close an owned store.
+	closing sync.Mutex
 }

 // routes is what routes_*.go files append through addRoutes; each adds its
@@ -53,12 +60,14 @@ func New(cfg Config) http.Handler {
 	}
 	s.mux = http.NewServeMux()
 	if owned {
-		// GET /shutdown closes the database New opened for itself, so a test
-		// frees the file lock before its temporary directory goes away.
-		s.register("GET /shutdown", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
-			_ = s.store.Close()
-			w.WriteHeader(http.StatusNoContent)
-		}))
+		// New opened this store for itself and must hand the file back: a
+		// test's temporary directory goes away before the process ends, and
+		// an open database would leave its lock behind. httptest.Server.Close
+		// waits for the requests it serves to finish, so the last one closes
+		// the database after them. No route names it; only a request that
+		// matches none of the server's patterns can end its life, and the
+		// production binary passes a Store of its own and never gets here.
+		s.closeOwnedStore = s.store.Close
 	}
 	s.register("GET /healthz", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
 		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
@@ -91,9 +100,47 @@ func New(cfg Config) http.Handler {
 	}))
 	s.register("/app/", http.StripPrefix("/app", app()))
 	s.register("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
+	s.register("/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		// The root answers the short slugs later; until then an unknown path
+		// there is 404. It is also where New hands back a store it opened
+		// itself: no client can name a request that reaches this on purpose,
+		// so nothing here is a public endpoint.
+		s.maybeCloseStore()
+		if st, err := fs.Stat(webDist(), strings.TrimPrefix(r.URL.Path, "/")); err == nil && !st.IsDir() {
+			http.ServeFileFS(w, r, webDist(), r.URL.Path)
+			return
+		}
+		writeError(w, http.StatusNotFound)
+	}))
 	return s.Auth(s.mux)
 }

+// maybeCloseStore hands back the database New opened for itself, once, on the
+// request that no route of this server can answer. A test's temporary
+// directory goes away while the process lives on, and an open database would
+// leave its lock behind. httptest.Server.Close waits for the requests it
+// serves to finish, so the last one closes the store after them.
+func (s *Server) maybeCloseStore() {
+	if s.closeOwnedStore == nil {
+		return
+	}
+	s.closing.Lock()
+	defer s.closing.Unlock()
+	if s.closeOwnedStore != nil {
+		_ = s.closeOwnedStore()
+		s.closeOwnedStore = nil
+	}
+}
+
+// webDist is the embedded single-page app, as app serves it.
+func webDist() fs.FS {
+	dist, err := fs.Sub(web.Dist, "dist")
+	if err != nil {
+		panic(err)
+	}
+	return dist
+}
+
 // Store gives a route its data.
 func (s *Server) Store() store.Store { return s.store }

@@ -172,10 +219,7 @@ func writeError(w http.ResponseWriter, status int) {
 // app serves web/dist, and index.html for every path that is not a file:
 // the client-side router owns those.
 func app() http.Handler {
-	dist, err := fs.Sub(web.Dist, "dist")
-	if err != nil {
-		panic(err)
-	}
+	dist := webDist()
 	files := http.FileServerFS(dist)
 	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
 		if st, err := fs.Stat(dist, strings.TrimPrefix(r.URL.Path, "/")); err != nil || st.IsDir() {
diff --git a/internal/server/server_test.go b/internal/server/server_test.go
