@@ -2,6 +2,7 @@ package server_test

 import (
 	"context"
+	"encoding/json"
 	"io"
 	"net/http"
 	"net/http/httptest"
@@ -61,8 +62,13 @@ func TestServerHealthz(t *testing.T) {
 	if got := res.Header.Get("Content-Type"); got != "application/json" {
 		t.Fatalf("Content-Type %q", got)
 	}
-	if !strings.Contains(string(body), `"status":"ok"`) {
-		t.Fatalf("body %q holds no status ok", body)
+	// Decoded, not matched as text: json.Encoder's spacing is its own.
+	var status map[string]string
+	if err := json.Unmarshal(body, &status); err != nil {
+		t.Fatalf("GET /healthz body %q is no JSON object: %v", body, err)
+	}
+	if status["status"] != "ok" {
+		t.Fatalf("GET /healthz status %q, want ok", status["status"])
 	}
 }

