cd /workspace/repo && cat > internal/server/zz_verify_test.go <<'EOF'
package server

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestVerifyProbeAll(t *testing.T) {
	for _, tc := range []struct{ name, first string }{
		{"no request at all", ""},
		{"healthz only", "/healthz"},
		{"unknown slug", "/nope123"},
		{"shutdown", "/shutdown"},
	} {
		dir := filepath.Join(t.TempDir(), "data")
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatal(err)
		}
		srv := httptest.NewServer(New(Config{DataDir: dir}))
		if tc.first != "" {
			r, _ := srv.Client().Get(srv.URL + tc.first)
			_ = r.Body.Close()
		}
		srv.Close()
		got := sideFiles(dir)
		t.Logf("%s: side files after Close = %d", tc.name, got)
		if got != 0 {
			t.Errorf("%s: owned store leaked (%d side files)", tc.name, got)
		}
	}
	// /shutdown must be a plain 404 with no special body
	dir := t.TempDir()
	srv := httptest.NewServer(New(Config{DataDir: dir}))
	defer srv.Close()
	res, err := http.Get(srv.URL + "/shutdown")
	if err != nil {
		t.Fatal(err)
	}
	buf := new(strings.Builder)
	_, _ = ioCopy(buf, res.Body)
	_ = res.Body.Close()
	t.Logf("GET /shutdown -> %d %q", res.StatusCode, buf.String())
	if res.StatusCode != http.StatusNotFound {
		t.Errorf("/shutdown answers %d, want 404", res.StatusCode)
	}
}

func ioCopy(dst *strings.Builder, src interface{ Read([]byte) (int, error) }) (int64, error) {
	buf := make([]byte, 512)
	var n int64
	for {
		c, err := src.Read(buf)
		if c > 0 {
			dst.Write(buf[:c])
			n += int64(c)
		}
		if err != nil {
			return n, err
		}
	}
}

func sideFiles(dir string) int {
	n := 0
	for _, s := range []string{"links.db-wal", "links.db-shm", "links.db-journal"} {
		if _, err := os.Stat(filepath.Join(dir, s)); err == nil {
			n++
		}
	}
	return n
}
EOF
go test -count=1 -run TestVerifyProbeAll -v ./internal/server/ 2>&1 | head -25; rm internal/server/zz_verify_test.go

