+	// code never issues a request, so there is no server-side fetch at all.
+	r, err := http.NewRequestWithContext(context.Background(), method, "http://short.example"+path, nil)
+	if err != nil {
+		return false
+	}
+	for _, m := range []string{"", method} {
+		// A request built with no method is a GET to ServeMux, so ask whether
+		// a bare pattern covers the path by looking for one first.
+		if m == "" && !s.hasBarePattern() {
+			continue
+		}
+		ask := *r
+		ask.Method = m
+		if _, matched := s.probe().Handler(&ask); matched != "" {
+			return true
+		}
+	}
